using Aspire.Hosting.Testing;

namespace MyApp.AppHost.Evaluation;

/// <summary>
/// Shared fixture that starts the distributed application once for all evaluation scenarios.
/// </summary>
public sealed class EvaluationFixture : IAsyncLifetime
{
    private DistributedApplication? _app;

    public DistributedApplication App => _app ?? throw new InvalidOperationException("App not started.");

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        builder.Services.ConfigureHttpClientDefaults(http =>
        {
            http.AddStandardResilienceHandler();
        });

        _app = await builder.BuildAsync();
        var cts = new CancellationTokenSource(TimeSpan.FromMinutes(3));
        await _app.StartAsync(cts.Token);
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

[CollectionDefinition(Name)]
public class EvaluationCollection : ICollectionFixture<EvaluationFixture>
{
    public const string Name = "Evaluation";
}

using Aspire.Hosting.Testing;

namespace MyApp.AppHost.Evaluation;

/// <summary>
/// Evaluates that the distributed application starts successfully and all resources become healthy.
/// </summary>
[Collection(EvaluationCollection.Name)]
public class AppStartsTests
{
    private readonly EvaluationFixture _fixture;

    public AppStartsTests(EvaluationFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task AppHost_Starts_Successfully()
    {
        // The fixture already starts the app; reaching here means startup succeeded.
        var app = _fixture.App;
        Assert.NotNull(app);
    }

    [Fact]
    public async Task All_Resources_Become_Healthy()
    {
        var app = _fixture.App;
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(120));

        // Wait for all resources to reach a running/healthy state.
        await app.WaitForResources(cts.Token);
    }
}

using System.Net;
using Aspire.Hosting.Testing;

namespace MyApp.AppHost.Evaluation;

/// <summary>
/// Evaluates end-to-end agent interaction scenarios.
/// </summary>
[Collection(EvaluationCollection.Name)]
public class AgentInteractionTests
{
    private readonly EvaluationFixture _fixture;

    public AgentInteractionTests(EvaluationFixture fixture)
    {
        _fixture = fixture;
    }

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task Agent_Responds_To_Prompt(string scenarioName, string input)
    {
        var app = _fixture.App;

        // Attempt to resolve an HTTP endpoint from the app's resources.
        // Adjust the resource name and endpoint as needed for your app topology.
        using var client = app.CreateHttpClient("webfrontend");

        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
        var response = await client.PostAsync(
            "/chat",
            new StringContent(
                System.Text.Json.JsonSerializer.Serialize(new { message = input }),
                System.Text.Encoding.UTF8,
                "application/json"),
            cts.Token);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);

        var body = await response.Content.ReadAsStringAsync(cts.Token);
        Assert.False(string.IsNullOrWhiteSpace(body), $"Scenario '{scenarioName}' returned empty response.");
    }

    public static TheoryData<string, string> GetScenarios() => new()
    {
        { "greeting", "Hello, what can you help me with?" },
        { "capability_check", "List your capabilities." },
    };
}

